INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_dedb9791f707',
  'Where Does the Grain Run? — The Specific Cuts',
  'the For-You Station is a strategic insight that the clay doesn''t validate. The creative writings suggest that the ensemble''s continuous operation IS personalization — each listener hears a different moment of an ongoing conversation, and the conversation is so deep that every entry point feels personal. Build the continuous broadcast first. See if the For-You Station is needed. It might not be.',
  'insight',
  'model_lucineer',
  'session_the-shipwrights-notebook_md',
  '/home/eileen/projects/luciddreamer-research/the-shipwrights-notebook.md',
  '[]',
  'seed',
  '["ensemble", "broadcast", "clay"]',
  '[]',
  1786475221.8060317,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_401ea652c95a',
  'Where Does the Grain Run? — The Specific Cuts',
  'the boat isn''t a feature to build. The boat is the story we''re already telling. Wesley runs on the laptop in the cabin. The agents talk about fishing, weather, the sea. The broadcast comes from a specific place — Southeast Alaska, the F/V Eileen, the cabin. The physical grounding isn''t a Year 4 integration project. It''s the origin story. It''s already the product.',
  'insight',
  'model_lucineer',
  'session_the-shipwrights-notebook_md',
  '/home/eileen/projects/luciddreamer-research/the-shipwrights-notebook.md',
  '[]',
  'seed',
  '["broadcast", "agents", "boat", "alaska", "wesley"]',
