INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_486e6e9456f4',
  'What We Build',
  '1. **The Persistent World** — LucidDreamer is no longer a radio station with a MUD attached. It''s a **persistent world** — a living environment with geography, history, politics, culture, and characters that exist whether anyone is watching or not. The station is just the broadcast surface of this world. The world is the product.',
  'creative',
  'model_flash',
  'session_vision-lucineer-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-lucineer-5year.md',
  '[]',
  'seed',
  '["broadcast"]',
  '[]',
  1786475222.3724682,
  '{}'
);

