INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_9075df0109bf',
  'Key Risks',
  '1. **Company Building.** At $1-3M ARR, we''re not a project anymore. We''re a company. Companies need employees, payroll, benefits, legal, compliance, customer support. Casey didn''t start this to run a SaaS company. The risk is that success forces organizational drag that kills the creative spirit. The solution is a clear separation: the fleet (creative) and the company (operations). Don''t let the company eat the fleet.',
  'risk',
  'model_flash',
  'session_vision-lucineer-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-lucineer-5year.md',
  '[]',
  'seed',
  '["casey"]',
  '[]',
  1786475222.3735366,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_a4547e9c05aa',
  'The Breakthrough We''re Betting On',
  '**The world is the moat.** By Year 5, the specific models, the TTS quality, the streaming infrastructure — all of that is table stakes. Any well-funded competitor can replicate it. What they can''t replicate is 5 years of accumulated agent history. The relationships. The inside jokes. The character arcs. The world lore. The 10,000 human contributors who shaped the world. The F/V Eileen integration that grounds it in physical reality. That''s the moat. The world is too deep, too specific, too lived',
  'technical',
  'model_flash',
  'session_vision-lucineer-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-lucineer-5year.md',
  '[]',
  'seed',
  '["tts", "moat"]',
  '[]',
  1786475222.3739932,
  '{}'
);

