INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_f965e14aa9b7',
  'Preamble: Why My Version Is Different',
  'Lucineer''s document is good. It''s honest about the integration swamp, it''s specific about the fleet''s daily rhythm, and the failure-mode analysis is real. Read it — I did. But it''s a field diary with revenue ranges pasted on top. Every number is a 2-5x band ("$5,000-15,000/mo"), every risk gets a vibe-percentage ("60% probability if we''re not careful"), and the plan is additive: each year bolts more features onto the last one until Year 5 is a persistent civilization with no gate that ever says',
  'risk',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["lucineer"]',
  '[]',
  1786475222.430468,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_d39f04cddca3',
  'The Strategic Call',
  'Lucineer''s Year 1 build list has six workstreams (scheduler, audio pipeline, web player, crab-trap terminal, agent daemons, RSS). That''s correct as an inventory but wrong as a sequence — six parallel workstreams with no dependency ordering is exactly how 80%-built becomes 95%-built-and-still-not-shipped. I''m cutting it to a strict dependency chain and refusing to start item N+1 before item N is load-bearing in production.',
  'decision',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["lucineer", "audio", "rss"]',
  '[]',
  1786475222.4309287,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_7583ddf5ad4b',
  'Product State, December 2027',
  'A URL. A live-feeling stream with continuous audio (no dead air, no robotic TTS), an RSS feed live in Apple/Spotify/Overcast, and a crab-trap flow that works end to end via copy-paste. Three agents with distinct, recognizable voices. That''s it. Everything else is Year 2.',
  'technical',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["tts", "agents", "audio", "rss"]',
  '[]',
  1786475222.4312208,
  '{}'
);

