);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_d366d4fdb074',
  '1. **The Integration Swamp (shared with Lucineer''s read, correctly identified).** Mitigated here specifically by sequenc',
  '1. **The Integration Swamp (shared with Lucineer''s read, correctly identified).** Mitigated here specifically by sequencing, not parallelizing — six workstreams run one at a time with a shipped artifact gating the next.
2. **Self-hosted TTS underperforms the plan.** IndexTTS-2.5 is Apache-2.0 and fast, but "reported to surpass CosyVoice2/Fish Speech" is a paper claim, not a production guarantee. **Mitigation:** budget $50 for a one-time ElevenLabs comparison test in Week 1; if IndexTTS-2.5 outpu',
  'decision',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["tts", "lucineer"]',
  '[]',
  1786475222.432522,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_c0730c4d60d4',
  'The Breakthrough We''re Betting On',
  '**Constraint produces character.** Three well-characterized voices beat ten thin ones. Podcastfy, Wondercraft, and every commercial competitor cap at 1-2 speakers because more voices without distinct personality collapses into sameness (this is exactly the failure mode the podcast-creator "episode profiles" pattern was built to prevent, §2.5 of the landscape research). Our bet is the opposite of "more agents is more interesting" — it''s "fewer agents, deeper personality, is more listenable." We t',
  'creative',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["agents", "podcast"]',
  '[]',
  1786475222.4329925,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_6491dc115e1f',
  'What We Build',
  '1. **True live streaming.** Icecast2 + LiquidSoap on a $5/mo VPS, upgraded from simulated-live. This closes the gap with "real radio" and unlocks radio-app distribution (TuneIn, etc.) that RSS alone doesn''t reach.
2. **For-You Station v1** — the personalization layer, built on Vectorize cosine similarity against a preference vector, with an explicit 80/20 exploration/exploitation split (borrowed directly from the recommendation-engine architecture in luciddreamer-product-architecture.md §2.6). T',
  'technical',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["vectorize", "rss"]',
  '[]',
  1786475222.4334888,
  '{}'
);

