INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_88cbd7187d6f',
  'The Breakthrough We''re Betting On',
  '**Separating "the world" from "the business" is what lets both survive contact with success.** The single biggest structural bet in this document, versus Lucineer''s: a persistent creative world and a recurring-revenue enterprise product have different success metrics, different cadences, and different tolerances for risk. Trying to run them as one initiative is what turns founders into people doing sales calls instead of creative direction — which is exactly the failure mode Lucineer''s own Year',
  'risk',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["lucineer"]',
  '[]',
  1786475222.4428341,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_99646be3753f',
  'The Moat — Three Things a Well-Funded Competitor Can''t Buy in 18 Months',
  'Lucineer lists five moat sources; most of them (ensemble dynamics, accumulated history, community) are real but time-based, meaning a sufficiently patient, sufficiently funded competitor eventually gets there too — they just have to wait, same as us. A strategic-ops read of "moat" asks a sharper question: **what can''t money and patience alone buy, even given 18 months and a blank check?**',
  'question',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
