INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_cc268abc4341',
  '1. The Validated Offline Distillation Architecture',
  'By Year 4, this isn''t a claim, it''s a measured result: a local model, distilled from cloud teachers, running a creative production loop through a real 72-hour zero-connectivity window on a physical fishing vessel. A competitor can fund a team to attempt this. They cannot fund their way past the calendar time required to *validate* it — you cannot compress "prove it survived a real 72-hour Alaska connectivity gap" into a sprint. This is the one moat source in the entire document that is genuinely',
  'blind_spot',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["alaska", "moat", "distillation", "offline"]',
  '[]',
  1786475222.4437897,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_508327462d3d',
  '2. The Depth-Over-Breadth Content Thesis, With A/B Data Behind It',
  'Every competitor in the podcast-generation landscape (Wondercraft, NotebookLM, Podcastfy) either caps at 1-2 speakers or, if they add more, doesn''t test whether more speakers help. This document''s entire five-year arc bets the opposite of the obvious "add more agents = richer ensemble" instinct, and — critically — tests that bet against real listener data starting Year 1. If the data says depth beats breadth, we''re the only player with the retention curves to prove it, and a competitor copying o',
  'insight',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["ensemble", "agents", "podcast"]',
  '[]',
  1786475222.4443605,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_6925212c0dc5',
  '3. The Two-Unit Org Structure Itself',
  'This sounds soft compared to a technical moat, but it''s the least copyable thing in the document. Most well-funded competitors entering this space will be either a media company bolting on AI (optimizing for Consumer, starving Enterprise) or an infra/AI company bolting on content (optimizing for Enterprise, treating Consumer as a demo). The discipline to run both simultaneously as genuinely separate units, sharing only the substrate, is an organizational choice that has to be made correctly from',
  'insight',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
  'seed',
  '["moat"]',
  '[]',
  1786475222.4448264,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_4bb8eb1d5a3b',
  'Failure Modes',
  'Lucineer''s three failure modes (demo that never ships, quality plateau, success kills us) are correct and I''m not going to pretend otherwise — read them, they''re right. Here''s what a strategic-ops lens adds: **each of Lucineer''s failure modes is a symptom; here are the two underlying disease patterns and the gates that catch them early, not late.**',
  'risk',
  'model_flash',
  'session_vision-claude-5year_md',
  '/home/eileen/projects/luciddreamer-research/vision-claude-5year.md',
  '[]',
