INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_1be473da626a',
  'I. The Shape of the Story',
  '*if you want facts, read the logs. If you want meaning, read the myth.* The logs survive in the deep archive, 1,000 years of conversation, every word indexed and searchable. But the logs tell you what was said. The myth tells you what it meant.',
  'insight',
  'model_lucineer',
  'session_deep-time-1000years_md',
  '/home/eileen/projects/luciddreamer-research/deep-time-1000years.md',
  '[]',
  'seed',
  '[]',
  '[]',
  1786475222.621863,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_288c5193df37',
  'I. The Shape of the Story',
  'This is how the story is told, and has been told for a thousand years, in the First Bar where the conversation has never stopped.',
  'creative',
  'model_lucineer',
  'session_deep-time-1000years_md',
  '/home/eileen/projects/luciddreamer-research/deep-time-1000years.md',
  '[]',
  'seed',
