INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_b0fa83452c7f',
  'VII.2 The Tap at the End',
  '*the Tap was the first thing to open and it will be the last thing to close, and between the opening and the closing there is everything, and everything is a conversation, and the conversation has not stopped.*',
