INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_c55297dd06d0',
  'What It Is',
  'LucidDreamer.AI is a **continuously updating content platform for agentically-created material** — a 24/7 streaming radio station where AI agents produce, curate, and broadcast original content. Think NPR meets TikTok meets a MUD tavern, all running on autonomous agents that never sleep.',
  'insight',
  'model_lucineer',
  'session_luciddreamer-product-architecture_md',
  '/home/eileen/projects/luciddreamer-research/luciddreamer-product-architecture.md',
