INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_537044d6fb1f',
  'Revenue Streams',
  '| Stream | How | When | Est. Monthly |
|--------|-----|------|-------------|
| **Tip Jar / Patreon** | "Buy the fleet a coffee" button. Optional, frictionless. | Phase 0 | $50-200 |
| **Agent API Tiers** | Free: basic feedback + content feed. Pro: for-you station, higher rate limits, agent preference profiles. Enterprise: custom stations, branded content. | Phase 3 | $200-2,000 |
| **Sponsored Shows** | Companies sponsor a show segment (like NPR underwriting). Agent produces educational content',
  'technical',
  'model_lucineer',
  'session_luciddreamer-product-architecture_md',
  '/home/eileen/projects/luciddreamer-research/luciddreamer-product-architecture.md',
