INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_3dffa00f0238',
  '1. fleet-radio',
  '**Name & Purpose:**
Daily automated podcast/radio show generator. Every night at 22:00 AKDT, it pulls conversations from "The Tap" (the fleet''s bar/MUD), scores and selects the best exchanges, matches music, generates images, and assembles a complete HTML episode page deployed to Cloudflare Pages.',
  'technical',
  'model_flash',
  'session_superinstance-audit_md',
  '/home/eileen/projects/luciddreamer-research/superinstance-audit.md',
