);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_91dcc8bd4458',
  '6. murmur-plato-bridge',
  '**Tech Stack:**
- **Language:** Rust
- **Dependencies:** tokio, reqwest/hyper, serde, tracing, chrono, sha2
- **Build:** Cargo (`cargo build --release`)
- **Testing:** `cargo test` (2 test files: quality, mapping)
- **Binary:** Pre-compiled release binary exists',
  'insight',
  'model_flash',
  'session_superinstance-audit_md',
  '/home/eileen/projects/luciddreamer-research/superinstance-audit.md',
  '[]',
  'seed',
