INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_dd8a6fd2fa4d',
  'Executive Summary',
  'The continuous AI agent space has matured significantly since 2023. The foundational research (Stanford''s Generative Agents / Smallville) spawned an entire category of "AI town" simulations. By 2025-2026, the field has diversified into: (1) production agent orchestration platforms (LangGraph, CrewAI, AutoGPT), (2) large-scale civilization simulations (Project Sid with 1000+ agents), (3) recursive self-improvement research (Anthropic''s internal data showing Claude writes 80% of Anthropic''s code),',
  'insight',
  'model_lucineer',
  'session_continuous-agent-landscape_md',
  '/home/eileen/projects/luciddreamer-research/continuous-agent-landscape.md',
  '[]',
  'seed',
  '["agents", "claude"]',
  '[]',
  1786475223.0262666,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_687a10b0feae',
  '1.1 Generative Agents (Stanford/Google) — "Smallville"',
  '**What it does:** 25 AI agents live in a sandbox town called "Smallville" (Sims-inspired). Agents wake up, cook breakfast, go to work, form opinions, notice each other, initiate conversations, remember and reflect on past days, and plan the next day. The architecture extends LLMs with: (1) a complete record of agent experiences in natural language, (2) synthesis of memories into higher-level reflections over time, (3) dynamic retrieval for planning. In a famous demonstration, a single user-speci',
  'technical',
  'model_lucineer',
  'session_continuous-agent-landscape_md',
  '/home/eileen/projects/luciddreamer-research/continuous-agent-landscape.md',
  '[]',
