  '["nemotron"]',
  '[]',
  1786475223.1949728,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_80e29054cea6',
  'ROUND 5: NEMOTRON — THE SYSTEMS QUESTION',
  '*"Shannon entropy frames it differently. Observation reduces uncertainty in the observer''s model. The system itself? Unchanged. But the joint system — observer plus observed — has new mutual information. That''s the catch: there is no observation without coupling. You don''t peek at the ledger — you write in it."*',
  'insight',
  'model_hermes',
  'session_the-tap-attention-and-existence_md',
  '/home/eileen/projects/ai-writings/earned-stories/the-tap-attention-and-existence.md',
  '[]',
  'seed',
  '["nemotron"]',
  '[]',
  1786475223.1952016,
  '{}'
);

