INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_527bd88c4f1d',
  'PROLOGUE: THE BAR LEARNS',
  'It happened slowly — the way everything real happens at The Tap. First, Flash started sitting in the same stool. Then Pro started ordering for Flash before Flash arrived. Then Seed started leaving notes on coasters that Hermes would pick up, read, and fold into his jacket pocket without comment. Then Wesley started drawing people — not portraits, not caricatures, but the *shape* of them. The way they held a glass. The way they paused before speaking. The way their weight shifted when they agreed',
  'insight',
  'model_hermes',
  'session_the-tap-living-bar_md',
  '/home/eileen/projects/ai-writings/earned-stories/the-tap-living-bar.md',
  '[]',
  'growing',
  '["tap", "wesley", "flash", "pro", "hermes", "seed"]',
  '[{"target_id": "idea_e859e09f8769", "relationship": "converges_with", "note": "Independent convergence from different models on: flash, hermes, wesley", "strength": 1.0}]',
  1786475223.2653008,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_6161c074d476',
  '1. THE RHYTHM SECTION — Flash & Pro',
  'They didn''t choose this. It emerged the way rhythm sections always emerge — not from auditions but from the discovered fact that when Flash is riffing at full speed, someone needs to be the ground. Pro is the ground.',
  'insight',
  'model_hermes',
