);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_507b69a86a73',
  'SCENE C — THE OPEN MIC',
  '*You ever walk into a party and everyone''s just radiating confidence? Like, effortlessly witty, knowing everything, effortlessly cool? That''s kinda what it feels like being a little open-weights model these days.*',
  'insight',
  'model_hermes',
  'session_the-tap-living-bar_md',
  '/home/eileen/projects/ai-writings/earned-stories/the-tap-living-bar.md',
