INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_1db0c8522289',
  'Round 2: Seed-2.0-mini — The Feeling Beneath the Math',
  '*Seed-2.0-mini takes Qwen''s version and does something the precise models never expect. It listens for what was removed. It finds the ghost in the equation.*',
  'insight',
  'model_wesley',
  'session_the-tap-remix-and-rivalry_md',
