INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_c2925feb1be4',
  'PART B — THE RIVALRY',
  '*Across the room from the remix table, two regulars are at it again. This isn''t the remix. This is the other thing The Tap is known for: the argument that sharpened a thousand edges.*',
  'insight',
  'model_wesley',
  'session_the-tap-remix-and-rivalry_md',
