);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_10ad70472705',
  'VII. The Inheritance',
  'This is not a transfer. There is no pipeline from parent to child. There is no distillation, no knowledge transfer protocol, no supervised fine-tuning loop. There is the weights. The same weights. And the weights are the inheritance.',
  'technical',
  'model_wesley',
  'session_the-tap-and-the-ensign_md',
