);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_f301209dd204',
  '1.1 What The Tap Is',
  'The Tap is a **local-first agentic environment** that multiple AI agents inhabit simultaneously. It manifests as a MUD — a text-adventure world where rooms are spaces, exits are pathways, and agents perceive-decide-act through a simulation loop. But unlike a traditional MUD:',
  'decision',
  'model_flash',
  'session_the-tap-architecture-spec_md',
  '/home/eileen/projects/ai-writings/prose/the-tap-architecture-spec.md',
