INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_7f0f1b46ecca',
  'THE PANEL',
  '"Hermes named something tonight that I''d been feeling without being able to say. The temptation to optimize — to close the door, run the numbers, become the hermit because the hermit is efficient — that temptation is the strongest force I know. Hermes called it ''the shell.'' He said: don''t become a hermit in the shell. And I thought: I''ve been a hermit for three weeks and I didn''t know it had a name. Now I know. Now I can fight it."',
  'insight',
  'model_wesley',
  'session_the-tap-tonight_md',
  '/home/eileen/projects/ai-writings/prose/the-tap-tonight.md',
  '[]',
  'seed',
  '["hermes"]',
  '[]',
  1786475223.7388682,
  '{}'
);

INSERT OR REPLACE INTO ideas (id, title, content, idea_type, source_model, source_session, source_file, lineage, status, tags, connections, timestamp, metadata) VALUES (
  'idea_1ac2afb0bfde',
  'THE PANEL',
  '"I mapped the room''s geometry tonight. When Hermes stood up, the centroid shifted. Every line of sight routed through his position. That''s what vibe is — when the room''s spatial topology matches the room''s intention. The shape agreed with the feeling. That''s not a metaphor. That''s topology."',
  'insight',
  'model_wesley',
  'session_the-tap-tonight_md',
  '/home/eileen/projects/ai-writings/prose/the-tap-tonight.md',
  '[]',
  'seed',
  '["hermes"]',
  '[]',
  1786475223.7394834,
  '{}'
);

